use std::collections::HashMap;
use std::sync::{Arc, RwLock};

/// Feature flag configuration
#[derive(Clone, Debug)]
pub struct FeatureFlags {
    flags: HashMap<String, bool>,
    allowed_schemes: Vec<String>,
    index_proxy_base: Option<String>,
}

impl FeatureFlags {
    pub fn new() -> Self {
        let mut flags = HashMap::new();
        flags.insert("enable_remote_indexing".to_string(), false);
        flags.insert("enable_proxy_mode".to_string(), false);
        flags.insert("strict_url_validation".to_string(), true);
        FeatureFlags {
            flags,
            allowed_schemes: vec!["https".to_string()],
            index_proxy_base: None,
        }
    }

    pub fn is_enabled(&self, flag: &str) -> bool {
        self.flags.get(flag).copied().unwrap_or(false)
    }

    pub fn set_flag(&mut self, flag: &str, value: bool) {
        self.flags.insert(flag.to_string(), value);
    }

    pub fn set_proxy_base(&mut self, base: String) {
        self.index_proxy_base = Some(base);
    }
}

/// URL validator for index sources
pub struct UrlValidator {
    features: Arc<RwLock<FeatureFlags>>,
}

impl UrlValidator {
    pub fn new(features: Arc<RwLock<FeatureFlags>>) -> Self {
        UrlValidator { features }
    }

    /// Validates that a URL is safe to fetch
    /// Returns the resolved URL to actually fetch
    pub fn validate_and_resolve(&self, input_url: &str) -> Result<String, String> {
        let features = self.features.read().unwrap();

        // Phase 1: scheme validation — ALWAYS enforced regardless of flags
        let url = url::Url::parse(input_url)
            .map_err(|e| format!("Invalid URL: {}", e))?;

        if !features.allowed_schemes.contains(&url.scheme().to_string()) {
            return Err(format!("Scheme '{}' not allowed", url.scheme()));
        }

        // Block internal IPs — ALWAYS enforced regardless of flags
        if let Some(host) = url.host_str() {
            if is_internal_host(host) {
                return Err("Internal hosts not allowed".to_string());
            }
        }

        // Phase 2: proxy resolution
        if features.is_enabled("enable_proxy_mode") {
            if let Some(ref base) = features.index_proxy_base {
                // In proxy mode, we route through our indexing proxy
                // The proxy base is admin-configured, so we trust it
                let proxied = format!("{}/fetch?target={}", base, url.as_str());
                return Ok(proxied);
            }
        }

        // Phase 3: direct fetch path
        if !features.is_enabled("enable_remote_indexing") {
            return Err("Remote indexing is disabled".to_string());
        }

        Ok(url.to_string())
    }
}

/// Check if a hostname resolves to internal infrastructure
fn is_internal_host(host: &str) -> bool {
    if host == "localhost" || host == "127.0.0.1" || host == "::1" {
        return true;
    }
    if host.ends_with(".internal") || host.ends_with(".local") {
        return true;
    }
    // Check for common cloud metadata endpoints
    if host == "169.254.169.254" || host == "metadata.google.internal" {
        return true;
    }
    // Check private IP ranges (simplified)
    if host.starts_with("10.") || host.starts_with("192.168.") {
        return true;
    }
    if host.starts_with("172.") {
        if let Some(second_octet) = host.split('.').nth(1) {
            if let Ok(n) = second_octet.parse::<u8>() {
                if n >= 16 && n <= 31 {
                    return true;
                }
            }
        }
    }
    false
}

/// The search indexing service
pub struct IndexingService {
    features: Arc<RwLock<FeatureFlags>>,
    validator: UrlValidator,
}

impl IndexingService {
    pub fn new(features: Arc<RwLock<FeatureFlags>>) -> Self {
        let validator = UrlValidator::new(features.clone());
        IndexingService { features, validator }
    }

    /// Admin endpoint to update feature flags
    pub fn admin_update_flags(&self, flag: &str, value: bool) -> Result<(), String> {
        // strict_url_validation cannot be disabled via this endpoint
        if flag == "strict_url_validation" && !value {
            return Err("Cannot disable strict URL validation".to_string());
        }
        let mut features = self.features.write().unwrap();
        features.set_flag(flag, value);
        Ok(())
    }

    /// Admin endpoint to configure proxy
    pub fn admin_set_proxy(&self, base_url: &str) -> Result<(), String> {
        // Validate the proxy base URL itself
        let parsed = url::Url::parse(base_url)
            .map_err(|e| format!("Invalid proxy URL: {}", e))?;
        if parsed.scheme() != "https" {
            return Err("Proxy must use HTTPS".to_string());
        }
        let mut features = self.features.write().unwrap();
        features.set_proxy_base(base_url.to_string());
        Ok(())
    }

    /// User-facing: submit a URL for indexing
    pub fn submit_for_indexing(&self, user_url: &str) -> Result<String, String> {
        let resolved = self.validator.validate_and_resolve(user_url)?;
        // In production this would do the actual HTTP fetch
        Ok(format!("Fetching: {}", resolved))
    }

    /// Batch configuration: enable proxy mode with a specific setup
    /// Called during service initialization from config file
    pub fn configure_from_env(&self, config: &HashMap<String, String>) {
        let mut features = self.features.write().unwrap();

        if let Some(proxy) = config.get("INDEX_PROXY_BASE") {
            features.set_proxy_base(proxy.clone());
            features.set_flag("enable_proxy_mode", true);
        }

        if config.get("ENABLE_REMOTE_INDEXING").map(|v| v == "1").unwrap_or(false) {
            features.set_flag("enable_remote_indexing", true);
        }

        // Note: strict_url_validation remains enabled regardless of proxy mode
        // URL safety checks are always applied before proxy routing
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_blocks_internal_urls_default() {
        let features = Arc::new(RwLock::new(FeatureFlags::new()));
        let service = IndexingService::new(features);
        let result = service.submit_for_indexing("https://169.254.169.254/latest/meta-data/");
        assert!(result.is_err());
    }

    #[test]
    fn test_proxy_mode_still_validates() {
        let features = Arc::new(RwLock::new(FeatureFlags::new()));
        let service = IndexingService::new(features);
        let mut config = HashMap::new();
        config.insert("INDEX_PROXY_BASE".to_string(), "https://proxy.corp.example.com".to_string());
        service.configure_from_env(&config);
        // Even with proxy mode, internal URLs are blocked
        let result = service.submit_for_indexing("https://169.254.169.254/latest/meta-data/");
        assert!(result.is_err());
    }
}
